async function _plCriarPedido(env, campos) {
  const tok = await _plTokenCasa(env);
  if (!tok) return { erro: 'a dash está sem o token da PayLog' };
  const fd = new FormData();
  for (const [k, v] of Object.entries(campos)) if (v != null && String(v) !== '') fd.append(k, String(v));
  try {
    const r = await _fetchComTeto('https://after.paylog.cash/api/v1/orders', 20000, {
      method: 'POST', headers: { Authorization: 'Bearer ' + tok, Accept: 'application/json' }, body: fd,
    });
    const txt = await r.text();
    let j = null; try { j = JSON.parse(txt); } catch (_) {}
    if (!r.ok) {
      const errs = (j && j.errors && typeof j.errors === 'object') ? Object.values(j.errors).flat().map(String) : [];
      const msg = (errs.length ? errs.join(' · ') : String((j && j.message) || txt || ('HTTP ' + r.status))).slice(0, 400);
      console.error('PAYLOG_ACEITE_RECUSADO http=' + r.status + ' ' + msg);
      return { erro: msg, status: r.status };
    }
    const code = String((j && ((j.data && j.data.code) || j.code || (j.order && j.order.code))) || '');
    console.log('PAYLOG_ACEITE_CRIADO code=' + code);
    return { ok: true, code };
  } catch (e) {
    // Timeout NAO quer dizer que nao criou. Quem confere e a busca pelo CPF, logo em seguida.
    return { erro: 'sem resposta da PayLog: ' + String((e && e.message) || e), incerto: true };
  }
}
// Devolve a Response do aceite com PayLog, ou null quando ele nao se aplica (o card ja esta numa
