    // pendurado segurava a rodada inteira do inbox - ver _dcApiGetRaw. 8s pra midia, que e maior.
    const r = await fetch(url, { signal: AbortSignal.timeout(8000) });   // CDN deles e publico: responde 200 sem Authorization (conferido com curl)
