    const ext = m.indexOf('ogg') >= 0 ? 'ogg' : (m.indexOf('mpeg') >= 0 || m.indexOf('mp3') >= 0) ? 'mp3' : m.indexOf('mp4') >= 0 ? 'mp4' : m.indexOf('png') >= 0 ? 'png' : (m.indexOf('jpeg') >= 0 || m.indexOf('jpg') >= 0) ? 'jpg' : m.indexOf('webp') >= 0 ? 'webp' : m.indexOf('pdf') >= 0 ? 'pdf' : 'bin';
