  // do afiliado punha 'afiliado_fdmx9z' como vendedor da pressel do Bruno. Mesma regra do
  // /pressels-total.json (_foraDoMundo): o mundo vem de users.afiliado_id; numero estacionado em
  // coluna (ccol_) e decidido pelo numero.
  const _mundoReq = (noMundoAfiliado(u) || afiliadoSemVinculo(u)) ? String(aflDe(u) || '\u0000') : '';
  const _aflDeAt = {}; try { const _ru = await env.DB.prepare("SELECT id, COALESCE(afiliado_id,'') afl FROM users").all(); for (const x of ((_ru && _ru.results) || [])) _aflDeAt[String(x.id)] = String(x.afl || ''); } catch (_) {}
