    const vc = M.vc[pid]||{};
    const p = { views:Number(vc.views)||0, clicks:Number(vc.clicks)||0, contatos:M.contatos[pid]||0, vendas:M.vendas[pid]||0, valor:M.valor[pid]||0, vend:{} };
    const cvi = M.contatosVI[pid]||{}, vvi = M.vendasVI[pid]||{};
