  const _fmtFone=(n)=>{ const d=String(n||'').replace(/\D/g,'').replace(/^55/,''); if(d.length<10) return String(n||'—'); const ddd=d.slice(0,2), r=d.slice(2); return '(' + ddd + ') ' + r.slice(0, r.length-4) + '-' + r.slice(-4); };
