  // Semeia um numero com ZERO, pra ele aparecer na lista mesmo sem ter recebido nada.
  // NUMEROS QUE RECEBERAM ALGUMA COISA HOJE, em qualquer linha da tabela. A semeadura com zero so
  // vale pra quem nao recebeu NADA: o mesmo numero pode ter leads gravados na linha de outro
  // vendedor (a conta Datacrazy do afiliado grava na instancia dele, sem os 8 digitos), e ai
  // semear zero faria o numero aparecer duas vezes, uma com 41 leads e outra com 0 - o tipo de
  // contradicao que faz a tela perder a confianca do Bruno.
  // O conjunto nasce vazio aqui e e preenchido dentro do ramo das metricas, assim que M e _pidsVer
  // existem - e antes da primeira chamada de _vendCell. Preencher nesta linha nao funcionaria: as
  // metricas ainda nem foram esperadas.
  const _k8ComLead = new Set();
  const _semeiaNum = (cel, k) => { if (!cel || !_podeNum || !k || _k8ComLead.has(k)) return; const pn = cel._pn || (cel._pn = {}); if (!pn[k]) pn[k] = { k, contatos: 0, vendas: 0 }; };
  const _fechaNum = (cel) => {
    const pn = Object.values((cel && cel._pn) || {});
    const lim = { ...cel }; delete lim._pn;
    if (!_podeNum || !pn.length) return lim;
    // Mais lead primeiro; empate pelo rotulo, pra a ordem nao dancar de um refresh pro outro. O
    // balde sem numero vai sempre por ultimo: ele e o resto, nao um numero da roleta.
    pn.sort((a, b) => (!a.k ? 1 : 0) - (!b.k ? 1 : 0) || (b.contatos - a.contatos) || (b.vendas - a.vendas) || String(a.k).localeCompare(String(b.k)));
    lim.porNum = pn.map((x) => ({ num: _rotuloNum(x.k), contatos: x.contatos, vendas: Number(x.vendas) || 0 }));
    return lim;
  };
  const _vendCell=(at)=>{ at=String(at); const mine=_chipsDo(at); let nums=mine.filter(_isEmUso).map(c=>c.num).filter(Boolean); if(!nums.length){ const any=mine[0]; nums.push((any&&any.num)||'—'); } const cel={at, name:_nomeCell(at), nums:(full?nums.map(_fmtFone):nums.map(n=>{ const p=String(n||'').replace(/\D/g,''); return p?('…'+p.slice(-4)):'—'; })), contatos:0, vendas:0};
    // Semeia com os numeros "Em uso" dele, pra o que ficou em ZERO aparecer na lista (ver o comentario acima).
    // So pra vendedor de verdade: `ccol_N` e coluna da Contingencia (so o diretor ve a linha) e
    // semear ali encheria a tabela com dezenas de numeros parados, todos zerados.
    if(_podeNum && !/^ccol_/i.test(at)){ try{ for(const c of mine){ if(!_isEmUso(c)) continue; _semeiaNum(cel, String(c.num||'').replace(/\D/g,'').slice(-8)); } }catch(_){} }
    return cel; };
  const _rankVend=(vend)=>{ const cv=(x)=>{ const c=Number(x.contatos)||0; return c>0?(Number(x.vendas)||0)/c:0; }; return (vend||[]).slice().sort((a,b)=> ((Number(b.vendas)||0)-(Number(a.vendas)||0)) || (cv(b)-cv(a)) || ((Number(b.contatos)||0)-(Number(a.contatos)||0))).map(_fechaNum); };
  // ── QUEM APARECE NA TABELA POR VENDEDOR ─────────────────────────────────────
