      let _fimF = (per === 'mes') ? (_proxMes.getTime() - 1) : new Date(day + 'T23:59:59.999-03:00').getTime();
      if (faixa) { _iniF = new Date(faixa.de + 'T00:00:00-03:00').getTime(); _fimF = new Date(faixa.ate + 'T23:59:59.999-03:00').getTime(); }
